<?php $pageTitle='Fornecedores'; require_once __DIR__.'/../../includes/header.php';
$action=$_GET['action']??''; $id=(int)($_GET['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0); $razao_social=trim($_POST['razao_social']??''); $documento=trim($_POST['documento']??''); $contato=trim($_POST['contato']??''); $email=trim($_POST['email']??''); $telefone=trim($_POST['telefone']??''); $status=trim($_POST['status']??''); if($id){$st=$pdo->prepare('UPDATE fornecedores SET razao_social=?,documento=?,contato=?,email=?,telefone=?,status=? WHERE id=?');$st->execute([$razao_social,$documento,$contato,$email,$telefone,$status,$id]);flash('ok','Registro atualizado.');}else{$st=$pdo->prepare('INSERT INTO fornecedores (razao_social,documento,contato,email,telefone,status) VALUES (?,?,?,?,?,?)');$st->execute([$razao_social,$documento,$contato,$email,$telefone,$status]);flash('ok','Registro cadastrado.');} header('Location: index.php');exit; }
if($action==='excluir'&&$id){$pdo->prepare('DELETE FROM fornecedores WHERE id=?')->execute([$id]);flash('ok','Registro removido.');header('Location: index.php');exit;}
$edit=null;if($action==='editar'&&$id){$st=$pdo->prepare('SELECT * FROM fornecedores WHERE id=?');$st->execute([$id]);$edit=$st->fetch();} $rows=$pdo->query('SELECT * FROM fornecedores ORDER BY id DESC')->fetchAll(); ?>
